            return today + datetime.timedelta(days=2)
        if "tomorrow" in s:
            return today + datetime.timedelta(days=1)
        if "today" in s:
            return today
        m = re.search(r"\b(\d{1,2})(st|nd|rd|th)?\b", s)
        if m:
            day = int(m.group(1))
            mo = [i + 1 for i, x in enumerate(MON) if x in s or x[:3] + " " in s + " "]
            if mo:
                d = datetime.date(today.year, mo[0], day)
                if d < today - datetime.timedelta(days=60):
                    d = datetime.date(today.year + 1, mo[0], day)
                return d
            d = datetime.date(today.year, today.month, day)
            if d < today:
                d = datetime.date(today.year + (1 if today.month == 12 else 0), today.month % 12 + 1, day)
